<script lang="ts">
  import {onMount} from 'svelte';
  import {computerClicks} from '../lib/computerClicks';
  import {observeStockMarket,financialBanReason} from '../game/core/financialRisk';
  import { gameState } from '../stores/gameStore.svelte';
  import { showToast } from '../stores/uiStore.svelte';
  import { advanceTime } from '../game/engine';
  import { STOCKS,STOCK_MAP,STOCK_RISK_LABEL } from '../game/data/stocks';
  import type { StockPosition,StockResult,StockSide } from '../game/stockTypes';
  import { placeStockOrder,cancelStockOrder,transferStockCash,setStockStop,takeStockLoan,repayStockDebt,stockCollateral,toggleStockFavorite,stockIsOverdue } from '../game/core/stockMarket';
  import { stockMinute,stockTimeLabel,stockAccountEquity,stockPositionEquity,stockPositionPnl,stockDebtTotal,stockFreeCash,stockFee,stockLiquidationPrice,interestDue,cents } from '../game/core/stockMath';
  import { buyInvestment,sellInvestment,investProductById } from '../game/core/invest';
  import StockChart from './StockChart.svelte';
  import StockHelp from './StockHelp.svelte';
  let {onclose=()=>{}}:{onclose?:()=>void}=$props();
  const s=gameState;
  onMount(()=>observeStockMarket(s));
  const riskMessage=$derived(financialBanReason(s,'stock'));
  const m=$derived(s.economy.stockMarket!);
  let selected=$state('SS001'),risk=$state('all'),search=$state(''),favoritesOnly=$state(false);
  let mainTab=$state('market'),lowerTab=$state('positions'),chartMode=$state<'trend'|'daily'>('trend');
  let side=$state<StockSide>('buy'),leverage=$state(2),orderType=$state('market'),quantity=$state<number|undefined>(1),limit=$state<number|undefined>(undefined),entryMode=$state('quantity'),budget=$state<number|undefined>(undefined),positionId=$state('');
  let advanced=$state(false),transfer=$state<number|undefined>(undefined),repayment=$state<number|undefined>(undefined),loanAmount=$state<number|undefined>(undefined),deposit=$state<number|undefined>(undefined),collateralIds=$state<string[]>([]),loanReview=$state(false);
  let stopDraft=$state<Record<string,string>>({}),message=$state(''),messageOk=$state(true);
  const def=$derived(STOCK_MAP[selected]),q=$derived(m.quotes[selected]),now=$derived(stockMinute(s)),free=$derived(stockFreeCash(m)),debt=$derived(stockDebtTotal(m));
  const listed=$derived(STOCKS.filter(stock=>(risk==='all'||stock.risk===risk)&&(!favoritesOnly||m.favorites.includes(stock.id))&&(!search||stock.name.includes(search)||stock.id.toLowerCase().includes(search.toLowerCase()))));
  const selectedPosition=$derived(m.positions.find(p=>p.id===positionId&&p.stockId===selected)??m.positions.find(p=>p.stockId===selected&&(side==='sell'?p.kind==='spot':side==='close'?p.kind!=='spot':true)));
  const isExit=$derived(side==='sell'||side==='close');
  const price=$derived(orderType==='limit'?cents(Number(limit)||0):q.priceCents);
  function costFor(n:number):number {const notional=n*price;return side==='buy'?notional+stockFee(notional):side==='long'||side==='short'?Math.ceil(notional/leverage)+stockFee(notional):0;}
  function fromBudget(amount:number):number {if(price<=0||amount<=0)return 0;let lo=0,hi=Math.min(1000000,Math.floor(amount*Math.max(1,leverage)/price));while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(costFor(mid)<=amount)lo=mid;else hi=mid-1;}return lo;}
  const tradeQty=$derived(entryMode==='budget'&&!isExit?fromBudget(cents(Number(budget)||0)):Number(quantity)||0);
  const notional=$derived(tradeQty*price),fee=$derived(tradeQty>0&&price>0?stockFee(notional):0),required=$derived(isExit?0:costFor(tradeQty));
  const collateral=$derived(stockCollateral(s)),collateralValue=$derived(collateral.filter(a=>collateralIds.includes(a.id)).reduce((n,a)=>n+a.valueCents,0)),loanMax=$derived(Math.floor(collateralValue*.6));
  const currentPnl=$derived(m.positions.reduce((n,p)=>n+stockPositionPnl(m,p),0));
  const tradeLabel=$derived(side==='buy'?'买入':side==='sell'?'卖出':side==='long'?'保证金做多':side==='short'?'保证金做空':selectedPosition?.kind==='short'?'买回平空':'卖出平多');
  const fmt=(value:number)=>(value/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const signed=(value:number)=>(value>=0?'+':'')+fmt(value);
  const pct=(value:number)=>(value>=0?'+':'')+(value*100).toFixed(2)+'%';
  const kindLabel=(p:StockPosition)=>p.kind==='spot'?'普通持股':(p.kind==='short'?'做空':'做多')+' '+p.leverage+'倍';
  function result(r:StockResult){message=r.reason;messageOk=r.ok;showToast(r.reason);}
  function pick(id:string){selected=id;positionId='';limit=undefined;}
  function chooseSide(value:StockSide){side=value;positionId='';quantity=1;entryMode='quantity';if(value==='long'&&leverage===1)leverage=2;}
  function quick(fraction:number){if(isExit){quantity=Math.floor(Math.max(0,(selectedPosition?.quantity??0)-m.orders.filter(o=>o.positionId===selectedPosition?.id).reduce((n,o)=>n+o.quantity,0))*fraction);}else{entryMode='quantity';quantity=fromBudget(Math.floor(free*fraction));}}
  function submit(){result(placeStockOrder(s,{stockId:selected,side,quantity:tradeQty,positionId:isExit?selectedPosition?.id:undefined,leverage:side==='long'||side==='short'?leverage:undefined,...(orderType==='limit'?{limitCents:price}:{})}));}
  function prepareClose(p:StockPosition){selected=p.stockId;side=p.kind==='spot'?'sell':'close';positionId=p.id;quantity=p.quantity;entryMode='quantity';orderType='market';mainTab='trade';}
  function saveStop(p:StockPosition){const raw=stopDraft[p.id]??(p.stopCents===null?'':String(p.stopCents/100));result(setStockStop(s,p.id,raw.trim()?cents(Number(raw)):null));}
  function waitForQuote(){const hours=(m.nextQuoteMinute-stockMinute(s))/60;advanceTime(s,hours);message='已推进到 '+stockTimeLabel(stockMinute(s))+'，时间与生活消耗照常结算。';messageOk=true;}
  function selectMain(tab:string){mainTab=tab;if(tab==='funds')lowerTab='funds';if(tab==='holdings'&&!['positions','orders','history','notices'].includes(lowerTab))lowerTab='positions';}
  function loanSubmit(){const r=takeStockLoan(s,cents(Number(loanAmount)||0),collateralIds);result(r);loanReview=false;if(r.ok)collateralIds=[];}
  function oldDeposit(){const r=buyInvestment(s,'deposit',Number(deposit)||0);result({ok:r.ok,reason:r.ok?'定期存款已存入':r.reason??'存入失败'});if(r.ok)deposit=undefined;}
  function redeem(id:string){const r=sellInvestment(s,id);result({ok:r.ok,reason:r.ok?'旧理财已赎回到生活现金':r.reason??'赎回失败'});}
</script>

<section class="ss-app" aria-label="顺顺花股票软件" use:computerClicks>
  {#if riskMessage}<p role="status" data-stock-risk-ban class="risk-banner">{riskMessage}</p>{/if}
  <header class="app-header"><div class="brand"><span class="brand-mark">顺</span><div><strong>顺顺花</strong><small>树堰证券 · 让每笔选择心中有数</small></div></div><div class="market-clock"><span class="live-dot"></span>更新于 <span>{stockTimeLabel(m.lastQuoteMinute)}</span></div><button class="close-app" aria-label="关闭顺顺花" onclick={onclose}>×</button></header>
  <div class="account-strip"><div><small>账户总值</small><strong>¥ {fmt(stockAccountEquity(m))}</strong></div><div><small>可用余额</small><strong>{fmt(free)}</strong></div><div><small>持仓盈亏</small><strong class:up={currentPnl>=0} class:down={currentPnl<0}>{signed(currentPnl)}</strong></div><div><small>待还款</small><strong class:debt={debt>0}>{fmt(debt)}</strong></div><div class="next-tick"><small>下次更新 {stockTimeLabel(m.nextQuoteMinute)}</small><button onclick={waitForQuote}>等待下次行情 ↗</button></div></div>
  <nav class="main-tabs" aria-label="软件页面">{#each [['market','行情市场'],['trade','买卖交易'],['holdings','持仓与委托'],['funds','资金与借款']] as tab}<button class:active={mainTab===tab[0]} onclick={()=>selectMain(tab[0])}>{tab[1]}</button>{/each}<span>06 / 12 / 18 / 24 更新</span></nav>
  {#if stockIsOverdue(m,now)}<div class="debt-alert" role="status">{m.gapDebts.length?'账户存在穿仓欠款':'抵押借款已逾期'} · 暂停新增买入和提现，请在宽限期内还款。<button onclick={()=>{mainTab='funds';lowerTab='loans';}}>查看还款</button></div>{/if}
  <div class="work-area" class:market-page={mainTab==='market'} class:trade-page={mainTab==='trade'} class:lower-page={mainTab==='holdings'||mainTab==='funds'}>
    <aside class="stock-list">
      <div class="list-controls"><div class="list-heading"><strong>市场行情 <em>12</em></strong><button class:chosen={favoritesOnly} onclick={()=>favoritesOnly=!favoritesOnly}>{favoritesOnly?'★ 自选':'☆ 自选'}</button></div><input aria-label="搜索股票" placeholder="搜索股票名称 / 代码" bind:value={search}/><select aria-label="股票风险筛选" bind:value={risk}><option value="all">全部类型</option><option value="stable">稳定</option><option value="medium">中等</option><option value="high">高波动</option></select></div>
      <div class="list-labels"><span>名称 / 代码</span><span>现价 / 本次</span></div><div class="stock-scroll">{#each listed as stock}{@const quote=m.quotes[stock.id]}<button class="stock-row" class:selected={stock.id===selected} aria-pressed={stock.id===selected} onclick={()=>pick(stock.id)}><span class="stock-name"><b>{stock.name}</b><small>{stock.id} <i class={'risk-'+stock.risk}>{STOCK_RISK_LABEL[stock.risk]}</i></small></span><span class="stock-number" class:up={quote.change>0} class:down={quote.change<0}><b>{fmt(quote.priceCents)}</b><small>{pct(quote.change)}</small><svg viewBox="0 0 60 14" aria-hidden="true"><polyline points={m.history.slice(-10).map((h,i,arr)=>{const vals=arr.map(p=>p.prices[stock.id]),low=Math.min(...vals),high=Math.max(...vals);return (i*60/Math.max(1,arr.length-1))+','+(12-(h.prices[stock.id]-low)/(high-low||1)*10);}).join(' ')} fill="none" stroke="currentColor" stroke-width="1.4"/></svg></span></button>{/each}{#if !listed.length}<p class="empty">没有匹配的股票</p>{/if}</div>
    </aside>
    <main class="quote-panel"><div class="quote-heading"><div><small>{selected} · {def.sector}</small><h2>{def.name}<button class="favorite" aria-label={m.favorites.includes(selected)?'移出自选':'加入自选'} onclick={()=>result(toggleStockFavorite(s,selected))}>{m.favorites.includes(selected)?'★':'☆'}</button></h2><span class={'risk-badge risk-'+def.risk}>{STOCK_RISK_LABEL[def.risk]}</span></div><div class="hero-price" class:up={q.change>=0} class:down={q.change<0}><strong>{fmt(q.priceCents)}</strong><span>本次 {pct(q.change)}</span></div></div><div class="quote-metrics"><span>今日涨跌 <b class:up={q.priceCents>=q.dayOpenCents} class:down={q.priceCents<q.dayOpenCents}>{pct(q.priceCents/q.dayOpenCents-1)}</b></span><span>上次报价 <b>{fmt(q.previousCents)}</b></span></div><div class="chart-tabs"><button class:active={chartMode==='trend'} onclick={()=>chartMode='trend'}>六小时走势</button><button class:active={chartMode==='daily'} onclick={()=>chartMode='daily'}>日K</button><span>{m.history.length} 次报价</span></div><StockChart history={m.history} stockId={selected} mode={chartMode} costCents={selectedPosition?selectedPosition.costCents/selectedPosition.quantity:null}/><div class="market-news"><span>公司动态</span><p>{q.event??'暂无公司新消息。'}</p></div><StockHelp topic="market"/></main>
    <aside class="trade-panel"><div class="panel-title"><strong>买卖股票</strong><span>可用 ¥ {fmt(free)}</span></div><label>交易股票<select aria-label="交易股票" value={selected} onchange={e=>pick(e.currentTarget.value)}>{#each STOCKS as stock}<option value={stock.id}>{stock.name} · {stock.id}</option>{/each}</select></label><div class="trade-quote"><span>当前价</span><b class:up={q.change>=0} class:down={q.change<0}>¥ {fmt(q.priceCents)}</b></div><div class="side-tabs"><button class:active={side==='buy'} onclick={()=>chooseSide('buy')}>买入</button><button class:active={side==='sell'} onclick={()=>chooseSide('sell')}>卖出</button>{#if side==='close'}<button class="active" onclick={()=>{}}>平仓</button>{/if}</div>
      <details bind:open={advanced} ontoggle={e=>{if(!e.currentTarget.open&&(side==='long'||side==='short'))chooseSide('buy');}}><summary>进阶交易</summary><div class="side-tabs"><button class:active={side==='long'} onclick={()=>chooseSide('long')}>做多 · 看涨</button><button class:active={side==='short'} onclick={()=>chooseSide('short')}>做空 · 看跌</button></div></details>
      {#if side==='long'||side==='short'}<label>杠杆倍数<select aria-label="杠杆倍数" bind:value={leverage}>{#if side==='short'}<option value={1}>1倍</option>{/if}<option value={2}>2倍</option><option value={3}>3倍</option></select></label>{/if}
      {#if isExit}<label>选择持仓<select aria-label="选择平仓持仓" bind:value={positionId}><option value="">自动选择一笔持仓</option>{#each m.positions.filter(p=>p.stockId===selected&&(side==='sell'?p.kind==='spot':p.kind!=='spot')) as p}<option value={p.id}>{kindLabel(p)} · {p.quantity} 股</option>{/each}</select></label>{#if !selectedPosition}<p class="empty">当前没有可用持仓</p>{/if}{/if}
      <label>委托方式<select aria-label="委托方式" bind:value={orderType}><option value="market">市价 · 按现价成交</option><option value="limit">限价 · 等指定价</option></select></label>
      {#if orderType==='limit'}<label>限价（元）<input aria-label="限价" type="number" min="0.01" step="0.01" bind:value={limit} placeholder={(q.priceCents/100).toFixed(2)}/></label>{/if}
      {#if !isExit}<div class="entry-toggle"><button class:active={entryMode==='quantity'} onclick={()=>entryMode='quantity'}>按股数</button><button class:active={entryMode==='budget'} onclick={()=>entryMode='budget'}>按预算</button></div>{/if}
      {#if entryMode==='budget'&&!isExit}<label>投入预算（元）<input aria-label="投入预算" type="number" min="0.01" step="0.01" bind:value={budget}/></label>{:else}<label>交易股数<input aria-label="交易股数" type="number" min="1" step="1" bind:value={quantity}/></label>{/if}
      <div class="quick-buttons">{#each [[.25,'1/4'],[.5,'半仓'],[1,'全部']] as item}<button onclick={()=>quick(Number(item[0]))}>{item[1]}</button>{/each}</div>
      <div class="order-preview"><div><span>本笔股数</span><b>{tradeQty} 股</b></div><div><span>交易金额</span><b>¥ {fmt(notional)}</b></div><div><span>手续费</span><b>¥ {fmt(fee)}</b></div>{#if !isExit}<div><span>{side==='buy'?'本笔需付':'保证金 + 手续费'}</span><b>¥ {fmt(required)}</b></div>{/if}{#if side==='long'||side==='short'}<div><span>预计强平价</span><b>¥ {fmt(Math.round(price*(1+(side==='short'?1:-1)*.75/leverage)))}</b></div><small>借款／借券年化6%，平仓时结清。</small>{/if}</div>
      <button class="submit-order" class:selling={isExit||side==='short'} disabled={tradeQty<1||!Number.isInteger(tradeQty)||price<1||(!isExit&&stockIsOverdue(m,now))} onclick={submit}>{orderType==='limit'?'提交限价':'确认'}{tradeLabel}</button><StockHelp topic={side} {orderType}/>
    </aside>
  </div>
  <section class="lower-panel" class:lower-page={mainTab==='holdings'||mainTab==='funds'}>
    <nav class="lower-tabs" aria-label="账户明细">{#each [['positions','我的持仓'],['orders','当前委托'],['history','成交记录'],['funds','资金与旧理财'],['loans','贷款与还款'],['notices','账户消息']] as tab}<button class:active={lowerTab===tab[0]} onclick={()=>lowerTab=tab[0]}>{tab[1]}{tab[0]==='orders'&&m.orders.length?' · '+m.orders.length:''}</button>{/each}</nav>
    <div class="lower-content">
    {#if lowerTab==='positions'}
      {#if !m.positions.length}<div class="empty-state"><span>⌁</span><strong>还没有持仓</strong><p>买入的股票会显示在这里。</p><button onclick={()=>{mainTab='funds';lowerTab='funds';}}>转入资金</button></div>
      {:else}<div class="table-scroll"><table><thead><tr><th>股票 / 类型</th><th>股数</th><th>成本 / 现价</th><th>浮动盈亏</th><th>当前权益 / 强平价</th><th>止损价（元）</th><th>操作</th></tr></thead><tbody>{#each m.positions as p}{@const pnl=stockPositionPnl(m,p)}{@const eq=stockPositionEquity(m,p)}<tr><td><button class="text-link" onclick={()=>{pick(p.stockId);mainTab='market';}}>{STOCK_MAP[p.stockId].name}</button><small>{kindLabel(p)}</small></td><td>{p.quantity}</td><td>{fmt(p.costCents/p.quantity)}<small>{fmt(m.quotes[p.stockId].priceCents)}</small></td><td class:up={pnl>=0} class:down={pnl<0}>{signed(pnl)}</td><td class:debt={p.kind!=='spot'&&eq<=p.marginCents*.5}>{fmt(eq)}{#if p.kind!=='spot'}<small>强平 {fmt(stockLiquidationPrice(p)!)} · 权益 {(eq/p.marginCents*100).toFixed(1)}%</small>{:else}<small>普通持股</small>{/if}</td><td><div class="stop-control"><input aria-label={'止损价 '+p.id} type="number" min="0.01" step="0.01" value={stopDraft[p.id]??(p.stopCents===null?'':p.stopCents/100)} oninput={e=>stopDraft[p.id]=e.currentTarget.value} placeholder="未设置"/><button onclick={()=>saveStop(p)}>保存</button>{#if p.stopCents!==null}<button onclick={()=>{stopDraft[p.id]='';result(setStockStop(s,p.id,null));}}>取消</button>{/if}</div></td><td><button onclick={()=>prepareClose(p)}>{p.kind==='spot'?'卖出':'平仓'}</button></td></tr>{/each}</tbody></table></div>{/if}
      <StockHelp topic="stop"/>
    {:else if lowerTab==='orders'}
      {#if !m.orders.length}<p class="empty">暂无等待成交的挂单。</p>{:else}<div class="table-scroll"><table><thead><tr><th>股票</th><th>方向</th><th>股数 / 限价</th><th>冻结资金</th><th>提交时间</th><th>操作</th></tr></thead><tbody>{#each m.orders as order}<tr><td>{STOCK_MAP[order.stockId].name}</td><td>{{buy:'买入',sell:'卖出',long:'做多',short:'做空',close:'平仓'}[order.side]}</td><td>{order.quantity} 股 · {fmt(order.limitCents)}</td><td>{fmt(order.reservedCents)}</td><td>{stockTimeLabel(order.createdMinute)}</td><td><button onclick={()=>result(cancelStockOrder(s,order.id))}>撤单</button></td></tr>{/each}</tbody></table></div>{/if}
      <StockHelp topic="limit"/>
    {:else if lowerTab==='history'}
      {#if !m.trades.length}<p class="empty">还没有成交记录。</p>{:else}<div class="table-scroll"><table><thead><tr><th>时间</th><th>股票 / 方向</th><th>股数 / 价格</th><th>手续费</th><th>已实现盈亏</th><th>成交原因</th></tr></thead><tbody>{#each [...m.trades].reverse() as trade}<tr><td>{stockTimeLabel(trade.minute)}</td><td>{STOCK_MAP[trade.stockId].name}<small>{trade.label}</small></td><td>{trade.quantity} 股 · {fmt(trade.priceCents)}</td><td>{fmt(trade.feeCents)}</td><td class:up={trade.pnlCents>=0} class:down={trade.pnlCents<0}>{signed(trade.pnlCents)}</td><td>{trade.reason}</td></tr>{/each}</tbody></table></div>{/if}
    {:else if lowerTab==='funds'}
      <div class="funds-grid"><article class="fund-card"><h3>转入与转出</h3><p>生活现金 <b>¥ {fmt(cents(s.player.money))}</b> · 证券可用 <b>¥ {fmt(free)}</b></p><div class="form-row"><input aria-label="资金划转金额" type="number" min="0.01" step="0.01" placeholder="金额（元）" bind:value={transfer}/><button onclick={()=>result(transferStockCash(s,cents(Number(transfer)||0),'in'))}>转入证券</button><button onclick={()=>result(transferStockCash(s,cents(Number(transfer)||0),'out'))}>转回生活</button></div><small>有未还借款时暂不能转出资金。</small><StockHelp topic="transfer"/></article><article class="fund-card"><h3>定期存款</h3><p>100元起存 · 月息0.13% · 按月结息</p><div class="form-row"><input aria-label="存入定期存款金额" type="number" min="100" step="1" placeholder="存款金额（元）" bind:value={deposit}/><button onclick={oldDeposit}>存入定期</button></div><StockHelp topic="deposit"/></article></div>
      <h3 class="section-heading">其他理财</h3>{#if !s.economy.investments.length}<p class="empty">暂无其他理财</p>{:else}<div class="legacy-grid">{#each s.economy.investments as inv}<div class="legacy-item"><div><strong>{investProductById(inv.productId)?.name??inv.productId}</strong><small>本金 {fmt(cents(inv.principal))} · 现值 {fmt(cents(inv.value))}</small></div><button onclick={()=>redeem(inv.id)}>赎回</button></div>{/each}</div>{/if}
      <StockHelp topic="legacy"/>
    {:else if lowerTab==='loans'}
      <div class="funds-grid"><article class="fund-card"><h3>待还款</h3><p>待还合计 <b class:debt={debt>0}>¥ {fmt(debt)}</b></p>{#if m.loan}<div class="loan-detail"><span>抵押本金 {fmt(m.loan.principalCents)} · 利息 {fmt(interestDue(m.loan))}</span><span>30天到期 {stockTimeLabel(m.loan.dueMinute)}</span><span>宽限截止 {stockTimeLabel(m.loan.deadlineMinute)} · {now>=m.loan.dueMinute?'年化12%':'年化6%'}</span></div>{/if}{#each m.gapDebts as d}<div class="loan-detail"><span>穿仓欠款 {fmt(d.principalCents)} · 利息 {fmt(interestDue(d))}</span><span>14天截止 {stockTimeLabel(d.deadlineMinute)} · 年化12%</span></div>{/each}<div class="form-row"><input aria-label="还款金额" type="number" min="0.01" step="0.01" placeholder="还款金额（元）" bind:value={repayment}/><button disabled={!debt} onclick={()=>result(repayStockDebt(s,cents(Number(repayment)||0)))}>还款</button><button disabled={!debt} onclick={()=>result(repayStockDebt(s,debt))}>尽力还清</button></div><small>优先用证券可用资金，再用生活现金；先还利息再还本金，部分还款不重置期限。</small><StockHelp topic="repay"/></article>
      <article class="fund-card"><h3>房车抵押借款</h3><p>选择名下房车，查看可借额度。</p>{#if !collateral.length}<p class="empty">还没有可以抵押的产权房或买断车辆。</p>{/if}<div class="collateral-list">{#each collateral as asset}<label><input type="checkbox" bind:group={collateralIds} value={asset.id} disabled={asset.pledged||!!m.loan} onchange={()=>loanReview=false}/><span>{asset.name}{asset.isHome?' · 自住':''}<small>估值 ¥ {fmt(asset.valueCents)}{asset.pledged?' · 已抵押':''}</small></span></label>{/each}</div><p>所选估值 <b>{fmt(collateralValue)}</b> · 可借额度 <b>{fmt(loanMax)}</b></p><div class="form-row"><input aria-label="抵押借款金额" type="number" min="0.01" step="0.01" bind:value={loanAmount} placeholder="借款金额（元）" oninput={()=>loanReview=false}/><button disabled={!!m.loan||!!m.gapDebts.length||!collateralIds.length} onclick={()=>loanReview=true}>查看借款确认</button></div>{#if loanReview}<div class="loan-review"><strong>确认抵押借款 ¥ {fmt(cents(Number(loanAmount)||0))}</strong><p>抵押：{collateral.filter(a=>collateralIds.includes(a.id)).map(a=>a.name).join('、')}</p><p>年化6%，到期 {stockTimeLabel(now+30*1440)}；逾期合计年化12%，宽限至 {stockTimeLabel(now+44*1440)}。届时仍欠款将变卖投资和房车偿债，可能失去自住房。</p><button onclick={loanSubmit}>确认抵押借款</button><button onclick={()=>loanReview=false}>返回修改</button></div>{/if}<small>贷款与保证金交易不能叠加；可提前还款，结清后解除抵押。</small><StockHelp topic="loan"/></article></div>
    {:else}
      {#if !m.notices.length}<p class="empty">暂时没有新消息。</p>{:else}{#each [...m.notices].reverse() as note}<div class="notice-row" class:debt={note.kind==='risk'}><time>{stockTimeLabel(note.minute)}</time><span>{note.text}</span></div>{/each}{/if}
    {/if}
    </div>
  </section>
  <footer class="status-bar" class:error={!messageOk} aria-live="polite"><span>{message||'每股起买 · 离开电脑后挂单继续有效'}</span><span>成交费0.05% · 最低0.01元</span></footer>
</section>

